class DeterministicRuntimeL3:
    def __init__(self, config: dict):
        self.psi_weight = config.get('psi_directional_weight', 1.0)
        self.force_table = config.get('force_active_line_weight', {})
        self.epsilon = config.get('safe_epsilon', 1e-7)  # PLACEHOLDER: Epsilon chống chia 0

    def compute_khi_5d_proven(self, que_chu, graph, gio_dia_chi) -> dict:
        # Đã chứng minh từ source dd_engine1/sie.py
        S = self._spatial_index(que_chu.active_line)
        D = self._directional_derivative(que_chu, self.psi_weight)
        I = self._interaction_density(graph)
        F = self._force_scalar(que_chu.active_line, graph, self.force_table)
        T = self._temporal_phase(que_chu.active_line, gio_dia_chi)
        return {'S': S, 'D': D, 'I': I, 'F': F, 'T': T}

    def compute_bec_field_unproven(self, khi_5d: dict) -> dict:
        # RESEARCH / PLACEHOLDER: Thiếu phụ lục gốc v2.8 (SL-DIF/BEC)
        # Giả định mô hình ngưng tụ BEC dạng an toàn có epsilon
        rho_condensate = min(1.0, max(0.0, khi_5d['I'] * khi_5d['F'] / (1.0 + self.epsilon)))
        return {'bec_condensation_density': rho_condensate, 'is_bec_boundary_valid': 0.0 <= rho_condensate <= 1.0}

    def step(self, snapshot_t: dict, inputs: dict) -> dict:
        # Deterministic transition S_t + I_t -> S_{t+1}
        khi_5d = self.compute_khi_5d_proven(inputs['que_chu'], inputs['graph'], inputs['gio_dia_chi'])
        bec_state = self.compute_bec_field_unproven(khi_5d)
        next_payload = {
            'raw_measurements': khi_5d,
            'field_state': bec_state,
            'uncertainty': {'khi_std': 0.0, 'model_confidence_variance': 0.05},
            'gate_result': {'gate_2_passed': True}
        }
        return {'tick': snapshot_t['tick'] + 1, 'payload': next_payload}

